then
    echo "[-] ERROR: Could not decode installer payload."
    rm -f "$TMP_TAR"
    exit 1
fi

if [ ! -s "$TMP_TAR" ] || ! tar -tzf "$TMP_TAR" >/dev/null 2>&1; then
    echo "[-] ERROR: Installer archive is empty or invalid."
    rm -f "$TMP_TAR"
    exit 1
fi

TTL_BACKUP_DIR="/root/ttl-hotspot-fix-backup-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$TTL_BACKUP_DIR" || { echo "[-] ERROR: Could not create TTL backup directory." >&2; exit 1; }
for ttl_path in /etc/firewall.user /etc/init.d/junspeedpatch /etc/hotplug.d/iface/96-junspeedpatch /etc/init.d/arc_antenna_switch /etc/init.d/3ginfo_ttl /etc/hotplug.d/iface/99-3ginfo-ttl /etc/firewall.d/3ginfo_ttl /etc/config/firewall /etc/config/ucitrack /www/luci-static/resources/view/modem/ttl.js; do
    if [ -f "$ttl_path" ]; then
        mkdir -p "$TTL_BACKUP_DIR$(dirname "$ttl_path")" && cp -p "$ttl_path" "$TTL_BACKUP_DIR$ttl_path" || { echo "[-] ERROR: Could not back up $ttl_path." >&2; exit 1; }
    fi
done

echo " [*] Extracting views, themes, PassWall 2, Tailscale, TTL and licensing..."
if ! tar -xzf "$TMP_TAR" -C /; then
    echo "[-] ERROR: Installer files could not be extracted."
    rm -f "$TMP_TAR"
    exit 1
fi
rm -f "$TMP_TAR"

# 2. Set execution permissions
chmod 0755 /usr/bin/junwrt-parental /etc/init.d/junwrt-parental /etc/hotplug.d/iface/98-junwrt-parental || exit 1
[ -f /etc/config/junwrt-parental ] || touch /etc/config/junwrt-parental || exit 1
/etc/init.d/junwrt-parental enable || exit 1
/etc/init.d/junwrt-parental restart || exit 1
echo " [+] Modem > Parental Control installed (no devices controlled by default)."
chmod 0755 /usr/bin/junwrt-speedtest || exit 1
echo " [+] Modem > Speed Test installed (runs only when started)."
# The vendor Wi-Fi state service ships without the execute bit, so saved radio on/off states were never restored.
[ ! -f /etc/init.d/wifi_state ] || chmod 0755 /etc/init.d/wifi_state || exit 1
chmod 0755 /etc/init.d/junspeedpatch /etc/init.d/arc_antenna_switch /etc/hotplug.d/iface/96-junspeedpatch || exit 1
/etc/init.d/arc_antenna_switch enable || exit 1
/etc/init.d/arc_antenna_switch restart </dev/null >/dev/null 2>&1 || exit 1
/etc/init.d/junspeedpatch enable || exit 1
/etc/init.d/junspeedpatch start </dev/null >/dev/null 2>&1 || exit 1
for module_file in /usr/bin/junwrt-guard /etc/init.d/junwrt-guard /usr/bin/junwrt-usage /etc/init.d/junwrt-usage /usr/bin/junwrt-notify /etc/init.d/junwrt-notify /etc/hotplug.d/iface/97-junwrt-notify /etc/init.d/3ginfo_sms_forward /usr/bin/junwrt-lights /etc/init.d/junwrt-lights /usr/bin/junwrt-security /usr/bin/junwrt-support; do
    chmod 0755 "$module_file" || exit 1
done
/etc/init.d/junwrt-guard enable 2>/dev/null || true
/etc/init.d/junwrt-guard restart 2>/dev/null || true
/etc/init.d/junwrt-usage enable 2>/dev/null || true
/etc/init.d/junwrt-usage restart 2>/dev/null || true
/etc/init.d/junwrt-notify enable 2>/dev/null || true
/etc/init.d/junwrt-notify restart 2>/dev/null || true
/etc/init.d/junwrt-lights enable 2>/dev/null || true
/etc/init.d/junwrt-lights restart 2>/dev/null || true
echo " [+] JunWRT modules installed (opt-in, off by default): Connection Guard, Data Usage, Notifications, Light Control, Security, Support."
chmod 0755 /usr/bin/junwrt-license 2>/dev/null || true
chmod 0755 /etc/init.d/junwrt-license 2>/dev/null || true
chmod 0755 /etc/rc.d/S98junwrt-license 2>/dev/null || true
chmod 0755 /etc/hotplug.d/iface/99-junwrt-license 2>/dev/null || true
chmod 0755 /etc/init.d/tailscale 2>/dev/null || true
chmod 0755 /usr/share/rpcd/ucode/tailscale.uc 2>/dev/null || true
chmod 0755 /usr/libexec/rpcd/tailscale 2>/dev/null || true
chmod 0755 /usr/bin/tailscale-helper 2>/dev/null || true
chmod 0755 /usr/bin/tailscale-cli-bootstrap 2>/dev/null || true
chmod 0755 /etc/init.d/tailscale-settings 2>/dev/null || true
chmod 0755 /usr/bin/junwrt-adblock 2>/dev/null || true
chmod 0755 /etc/init.d/junwrt-adblock 2>/dev/null || true
chmod 0755 /usr/share/rpcd/ucode/junwrt-adblock.uc 2>/dev/null || true
chmod 0755 /etc/init.d/3ginfo_ttl 2>/dev/null || true
chmod 0755 /etc/hotplug.d/iface/99-3ginfo-ttl 2>/dev/null || true
chmod 0755 /usr/share/3ginfo-lite/3ginfo.sh 2>/dev/null || true
chmod 0755 /www/cgi-bin/junwrt-wallpaper 2>/dev/null || true

# Keep ad blocking opt-in and preserve any existing user configuration.
if [ ! -s /etc/config/junwrt-adblock ]; then
    printf "config adblock 'main'
	option enabled '0'
	option source '%s'
" 'https://raw.githubusercontent.com/StevenBlack/hosts/master/hosts' > /etc/config/junwrt-adblock || { echo "[-] ERROR: Could not create Ad Blocker configuration." >&2; exit 1; }
fi
uci -q get junwrt-adblock.main >/dev/null 2>&1 || uci -q set junwrt-adblock.main=adblock
[ -n "$(uci -q get junwrt-adblock.main.enabled 2>/dev/null)" ] || uci -q set junwrt-adblock.main.enabled='0'
[ -n "$(uci -q get junwrt-adblock.main.source 2>/dev/null)" ] || uci -q set junwrt-adblock.main.source='https://raw.githubusercontent.com/StevenBlack/hosts/master/hosts'
uci -q commit junwrt-adblock 2>/dev/null || true

# Install the TTL/hotspot firewall hook and refresh its LAN-to-WAN rules.
/etc/init.d/3ginfo_ttl enable || { echo "[-] ERROR: Could not enable the TTL hotspot service." >&2; exit 1; }
/etc/init.d/3ginfo_ttl reload || { echo "[-] ERROR: Could not reload the TTL hotspot rules." >&2; exit 1; }
echo " [+] TTL hotspot service and WAN hotplug hook installed."
echo " [+] TTL backup: $TTL_BACKUP_DIR"

# 3. Set Hostname to JunWRT (Updates root@JunWRT in SSH & WebUI)
echo " [*] Updating System Hostname to JunWRT..."
uci set system.@system[0].hostname='JunWRT' 2>/dev/null || true
uci commit system 2>/dev/null || true
echo "JunWRT" > /proc/sys/kernel/hostname 2>/dev/null || true

# 4. Initialize Machine ID & Licensing Service
[ -s /etc/junwrt_machine_id ] || /usr/bin/junwrt-license machine-id > /etc/junwrt_machine_id 2>/dev/null || true
chmod 0644 /etc/junwrt_machine_id 2>/dev/null || true

# Ensure firewall hook exists
[ -f /etc/firewall.user ] || printf '#!/bin/sh
' > /etc/firewall.user || exit 1
if ! grep -Fq '# BEGIN JUNWRT_MSS_V1' /etc/firewall.user; then
    cat >> /etc/firewall.user << 'EOF_MSS_HOOK'

# BEGIN JUNWRT_MSS_V1
for junwrt_mss_tool in iptables ip6tables; do
    command -v "$junwrt_mss_tool" >/dev/null 2>&1 || continue
    "$junwrt_mss_tool" -t mangle -C FORWARD -p tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null ||         "$junwrt_mss_tool" -t mangle -A FORWARD -p tcp --tcp-flags SYN,RST SYN -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null || true
done
# END JUNWRT_MSS_V1
EOF_MSS_HOOK
fi
chmod 0755 /etc/firewall.user || exit 1
grep -q "junwrt-license enforce-firewall" /etc/firewall.user 2>/dev/null || {
    echo "" >> /etc/firewall.user
    echo "# JunWRT Commercial Licensing Enforcement Hook" >> /etc/firewall.user
    echo "/usr/bin/junwrt-license enforce-firewall 2>/dev/null || true" >> /etc/firewall.user
}

/etc/init.d/junwrt-license enable 2>/dev/null || true
/etc/init.d/junwrt-license restart 2>/dev/null || true
/usr/bin/junwrt-license enforce-firewall 2>/dev/null || true

# 5. Set Argon as default theme
uci set luci.main.mediaurlbase='/luci-static/argon' 2>/dev/null || true
uci commit luci 2>/dev/null || true

# 6. Tailscale Configuration & OpenWrt Firewall Integration
echo " [*] Configuring Tailscale (RAM optimization & Direct P2P Firewall)..."
uci set tailscale.settings.fw_mode='iptables' 2>/dev/null || true
uci set tailscale.settings.low_memory='1' 2>/dev/null || true
uci set tailscale.settings.port='41641' 2>/dev/null || true
uci commit tailscale 2>/dev/null || true

# Some JunWRT builds ship a tailscaled-only binary behind /usr/sbin/tailscale.
# Install the matching standalone CLI so Tailscale status and login can work.
if [ -x /usr/bin/tailscale-cli-bootstrap ]; then
    if /usr/bin/tailscale-cli-bootstrap; then
        echo " [+] Matching Tailscale CLI is ready."
    else
        echo " [!] Tailscale CLI setup failed; check WAN access and package version."
    fi
fi

# Auto-configure Tailscale network interface
uci -q get network.tailscale >/dev/null 2>&1 || {
    uci set network.tailscale=interface
    uci set network.tailscale.proto='none'
    uci set network.tailscale.device='tailscale0'
    uci commit network
}

# Auto-configure Tailscale firewall zone & forwardings
FW_MODIFIED=0
HAS_ZONE=0
for section_id in $(uci show firewall | sed -n 's/^firewall\.\([^=]*\)=zone$/\1/p'); do
    current_zone="$(uci -q get "firewall.$section_id.name" 2>/dev/null)"
    if [ "$current_zone" = "tailscale" ]; then
        HAS_ZONE=1
        break
    fi
done

if [ "$HAS_ZONE" = "0" ]; then
    uci add firewall zone >/dev/null || exit 1
    uci set "firewall.@zone[-1].name=tailscale" || exit 1
    uci add_list "firewall.@zone[-1].network=tailscale" || exit 1
    uci add_list "firewall.@zone[-1].device=tailscale0" || exit 1
    uci set "firewall.@zone[-1].input=ACCEPT" || exit 1
    uci set "firewall.@zone[-1].output=ACCEPT" || exit 1
    uci set "firewall.@zone[-1].forward=ACCEPT" || exit 1
    uci set "firewall.@zone[-1].masq=1" || exit 1
    uci set "firewall.@zone[-1].mtu_fix=1" || exit 1
    FW_MODIFIED=1
fi

ensure_tailscale_forwarding() {
    wanted_src="$1"
    wanted_dest="$2"

    for section_id in $(uci show firewall | sed -n 's/^firewall\.\([^=]*\)=forwarding$/\1/p'); do
        current_src="$(uci -q get "firewall.$section_id.src" 2>/dev/null)"
        current_dest="$(uci -q get "firewall.$section_id.dest" 2>/dev/null)"
        if [ "$current_src" = "$wanted_src" ] && [ "$current_dest" = "$wanted_dest" ]; then
            return 0
        fi
    done

    uci add firewall forwarding >/dev/null || return 1
    uci set "firewall.@forwarding[-1].src=$wanted_src" || return 1
    uci set "firewall.@forwarding[-1].dest=$wanted_dest" || return 1
    FW_MODIFIED=1
}

# Ensure each LAN/WAN direction exists only once, including on installer reruns.
ensure_tailscale_forwarding lan tailscale || exit 1
ensure_tailscale_forwarding tailscale lan || exit 1
ensure_tailscale_forwarding wan tailscale || exit 1
ensure_tailscale_forwarding tailscale wan || exit 1

# Allow WAN incoming UDP port 41641 for direct WireGuard P2P tunnels
HAS_UDP_RULE=0
for section_id in $(uci show firewall | sed -n 's/^firewall\.\([^=]*\)=rule$/\1/p'); do
    if [ "$(uci -q get "firewall.$section_id.name" 2>/dev/null)" = 'Allow-Tailscale-WireGuard' ] &&
       [ "$(uci -q get "firewall.$section_id.src" 2>/dev/null)" = wan ] &&
       [ "$(uci -q get "firewall.$section_id.proto" 2>/dev/null)" = udp ] &&
       [ "$(uci -q get "firewall.$section_id.dest_port" 2>/dev/null)" = 41641 ] &&
       [ "$(uci -q get "firewall.$section_id.target" 2>/dev/null)" = ACCEPT ]; then
        HAS_UDP_RULE=1
        break
    fi
done

if [ "$HAS_UDP_RULE" = "0" ]; then
    uci add firewall rule >/dev/null
    uci set firewall.@rule[-1].name='Allow-Tailscale-WireGuard'
    uci set firewall.@rule[-1].src='wan'
    uci set firewall.@rule[-1].proto='udp'
    uci set firewall.@rule[-1].dest_port='41641'
    uci set firewall.@rule[-1].target='ACCEPT'
    FW_MODIFIED=1
fi

if [ "$FW_MODIFIED" = "1" ]; then
    uci commit firewall || exit 1
fi
if [ "$LEGACY_LICENSE_RULES" = "1" ]; then
    /etc/init.d/firewall restart </dev/null >/dev/null 2>&1 || { echo "[-] ERROR: Legacy license firewall migration failed." >&2; exit 1; }
elif [ "$FW_MODIFIED" = "1" ]; then
    /etc/init.d/firewall reload </dev/null >/dev/null 2>&1 || { echo "[-] ERROR: Firewall reload failed." >&2; exit 1; }
fi

# The reload restarts the Wi-Fi daemon (wapp), which keeps its parent's terminal as its output and
# would print debug lines into this SSH session until it ends, so run the reload detached from it.
/etc/init.d/network reload </dev/null >/dev/null 2>&1 || true
/etc/init.d/tailscale enable 2>/dev/null || true
/etc/init.d/tailscale restart 2>/dev/null || true

# 7. Clean conflicting legacy files
rm -f /www/luci-static/resources/view/status/include/25_traffic_wifi.js 2>/dev/null || true

# 8. Flush LuCI cache & reload web server / rpcd
echo " [*] Flushing LuCI cache & restarting web server / rpcd..."
rm -rf /tmp/luci-indexcache /tmp/luci-modulecache /tmp/tailscale_login.log /tmp/tailscale_auth_url 2>/dev/null || true
# Blocklist downloads can outlast the stock 30-second file.exec timeout.
RPCD_TIMEOUT="$(uci -q get 'rpcd.@rpcd[0].timeout' 2>/dev/null)"
case "$RPCD_TIMEOUT" in ''|*[!0-9]*) RPCD_TIMEOUT=0 ;; esac
if [ "$RPCD_TIMEOUT" -lt 120 ]; then
    uci -q set 'rpcd.@rpcd[0].timeout=120' && uci -q commit rpcd || {
        echo " [-] ERROR: Could not extend the RPC command timeout."
        exit 1
    }
fi
/etc/init.d/rpcd restart 2>/dev/null || true
/etc/init.d/uhttpd restart 2>/dev/null || true
/usr/bin/junwrt-license enforce-firewall 2>/dev/null || true

# 9. Self-check: every file this installer wrote must match the manifest shipped inside it.
echo " [*] Verifying installed files..."
VERIFY_TOTAL=0
VERIFY_BAD=0
while read -r verify_sum verify_path; do
    [ -n "$verify_path" ] || continue
    VERIFY_TOTAL=$((VERIFY_TOTAL + 1))
    verify_got="$(sha256sum "$verify_path" 2>/dev/null | cut -d' ' -f1)"
    if [ "$verify_got" != "$verify_sum" ]; then
        VERIFY_BAD=$((VERIFY_BAD + 1))
        echo " [-] Missing or different: $verify_path"
    fi
done < /etc/junwrt-webui.manifest
INSTALLED_BUILD="$(sed -n 's/^built=//p' /etc/junwrt-webui.build 2>/dev/null | head -n 1)"
if [ "$VERIFY_BAD" = 0 ] && [ "$VERIFY_TOTAL" -gt 0 ]; then
    VERIFY_LINE=" [+] Self-check passed: $VERIFY_TOTAL files match build $INSTALLED_BUILD"
else
    VERIFY_LINE=" [!] Self-check: $VERIFY_BAD of $VERIFY_TOTAL files differ - run this installer again"
fi

echo "=================================================================="
if [ "$VERIFY_BAD" != 0 ] || [ "$VERIFY_TOTAL" -eq 0 ]; then
    echo " [-] ERROR: JunWRT installation verification failed."
    echo "$VERIFY_LINE"
    echo " [-] Review the mismatched files above before treating this install as complete."
    exit 1
fi
echo " [+] SUCCESS: JunWRT Unified WebUI Suite Installed!               "
echo "$VERIFY_LINE"
echo " [+] Hostname: JunWRT (Prompt will show root@JunWRT)              "
echo " [+] Cockpit & 8 Modem Pages (Light White / Dark Gray) active      "
echo " [+] PassWall 2 Modern UI & Node-via-Link active                  "
echo " [+] Tailscale Anti-OOM (48MB limit) & 1-Click Auth Key active    "
echo " [+] DNS Ad Blocker (opt-in blocklists) available                 "
echo " [+] Speed Test & Tower Analyzer (Modem menu) available          "
echo " [+] TTL hotspot fix (IPv4 TTL / IPv6 Hop Limit) active           "
echo " [+] Open http://192.168.1.1 (Refresh with Ctrl+Shift+R)          "
echo "=================================================================="
exit 0
